$ErrorActionPreference = "Stop"

function Write-Section($msg) {
  Write-Host "`n=== $msg ===" -ForegroundColor Cyan
}

$root = Split-Path -Parent $MyInvocation.MyCommand.Path
Set-Location $root

if (-not (Test-Path (Join-Path $root 'package.json'))) {
  throw "Run this script from your frontend root folder (the folder that contains package.json)."
}

$timestamp = Get-Date -Format 'yyyyMMdd_HHmmss'
$backupDir = Join-Path $root ("_frontend_replace_backup_" + $timestamp)
$extractDir = Join-Path $root ("_frontend_replace_extract_" + $timestamp)
$payloadZip = Join-Path $root ("_frontend_replace_payload_" + $timestamp + '.zip')

$targets = @(
  'src',
  'public',
  'index.html',
  'components.json',
  'eslint.config.js',
  'postcss.config.js',
  'tailwind.config.ts',
  'vite.config.ts',
  'tsconfig.json',
  'tsconfig.app.json',
  'tsconfig.node.json',
  'vitest.config.ts',
  'playwright.config.ts',
  'playwright-fixture.ts',
  'README.md',
  'package.json',
  'package-lock.json',
  'bun.lock',
  'bun.lockb'
)

Write-Section "Backing up current frontend files"
New-Item -ItemType Directory -Force -Path $backupDir | Out-Null
foreach ($item in $targets) {
  $src = Join-Path $root $item
  if (Test-Path $src) {
    Move-Item -LiteralPath $src -Destination (Join-Path $backupDir $item) -Force
  }
}

