[System.IO.File]::WriteAllBytes($payloadZip, [System.Convert]::FromBase64String($base64))

Write-Section "Extracting new frontend"
Expand-Archive -LiteralPath $payloadZip -DestinationPath $extractDir -Force

Write-Section "Copying new frontend files into place"
Get-ChildItem -LiteralPath $extractDir -Force | ForEach-Object {
  $dest = Join-Path $root $_.Name
  Copy-Item -LiteralPath $_.FullName -Destination $dest -Recurse -Force
}

Write-Section "Preserved automatically"
Write-Host "Kept existing electron/ folder (if present)" -ForegroundColor Yellow
Write-Host "Kept existing .env / env-related files" -ForegroundColor Yellow
Write-Host "Kept existing node_modules/ folder" -ForegroundColor Yellow

Write-Section "Installing frontend dependencies"
cmd /c npm install
if ($LASTEXITCODE -ne 0) { throw "npm install failed with exit code $LASTEXITCODE" }

Write-Section "Building renderer to verify replacement"
cmd /c npm run build
if ($LASTEXITCODE -ne 0) { throw "npm run build failed with exit code $LASTEXITCODE" }

Write-Section "Cleaning temp payload files"
if (Test-Path $payloadZip) { Remove-Item -LiteralPath $payloadZip -Force }
if (Test-Path $extractDir) { Remove-Item -LiteralPath $extractDir -Recurse -Force }

Write-Section "Frontend replacement complete"
Write-Host "Backup saved to: $backupDir" -ForegroundColor Green
Write-Host "Next dev command:" -ForegroundColor Green
Write-Host "  npm run dev" -ForegroundColor White
Write-Host "Optional desktop dev command:" -ForegroundColor Green
Write-Host "  npm run dev:desktop" -ForegroundColor White
